use xiom.io;
type Student = {
  id: Int;
  name: Str;
}

fn find_by_id_vec(students: &Vec[Student], id: Int) -> Option[Str] {
  let i = 0;
  while i < students.len() {
    let s = match students.get(i) { Some(v) => v, None => continue };
    if s.id == id {
      return Some(s.name);
    }
    i = i + 1;
  }
  return None;
}

fn find_by_id_map(students: &Map[Int, Str], id: Int) -> Option[Str] {
  return students.get(&id);
}

fn main() -> Int {
  let vec_students: Vec[Student] = Vec[Student].new();
  vec_students.push(Student{ id: 101, name: "Alice" });
  vec_students.push(Student{ id: 102, name: "Bob" });
  vec_students.push(Student{ id: 103, name: "Carol" });

  let map_students: Map[Int, Str] = Map[Int, Str].new();
  map_students.insert(101, "Alice");
  map_students.insert(102, "Bob");
  map_students.insert(103, "Carol");

  let v = find_by_id_vec(&vec_students, 102);
  let m = find_by_id_map(&map_students, 102);

  io.println(match v { Some(n) => "Vec: " + n, None => "Vec: not found" });
  io.println(match m { Some(n) => "Map: " + n, None => "Map: not found" });
  return 0;
}
